  "content": "<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Anotify · API Keys</title>
    <link rel="icon" type="image/svg+xml" href="../public/favicon.svg" />
    <script src="https://cdn.tailwindcss.com"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link
      href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Fraunces:ital,opsz,wght@0,9..144,340;0,9..144,420;1,9..144,400&display=swap"
      rel="stylesheet"
    />
    <link rel="stylesheet" href="../public/fonts/fonts.css" />
    <style>
      :root {
        --bg: #050508;
        --panel: rgba(255, 255, 255, 0.03);
        --line: rgba(255, 255, 255, 0.08);
        --line-strong: rgba(255, 255, 255, 0.14);
        --text: #ececf1;
        --muted: rgba(236, 236, 241, 0.55);
        --faint: rgba(236, 236, 241, 0.32);
        --accent: #8b8bfd;
        --accent-soft: rgba(139, 139, 253, 0.12);
      }
      * { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
      body {
        font-family: "Inter", system-ui, sans-serif;
        background: var(--bg);
        color: var(--text);
        font-feature-settings: "ss01", "cv11", "liga";
      }
      .font-script { font-family: "Sacramento", "Great Vibes", cursive; }
      .font-display { font-family: "Fraunces", Georgia, serif; }
      ::selection { background: rgba(139, 139, 253, 0.35); color: #fff; }
      ::-webkit-scrollbar { width: 8px; height: 8px; }
      ::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.1); border-radius: 8px; }
      ::-webkit-scrollbar-track { background: transparent; }
      .card {
        background: rgba(255, 255, 255, 0.02);
        border: 1px solid var(--line);
        border-radius: 16px;
        transition: border-color 0.3s ease;
      }
      .card:hover { border-color: var(--line-strong); }
      .side-link {
        display: flex; align-items: center; gap: 0.7rem;
        padding: 0.55rem 0.8rem; border-radius: 10px;
        font-size: 0.875rem; color: var(--muted);
        border: 1px solid transparent; transition: all 0.2s ease;
      }
      .side-link:hover { color: var(--text); background: rgba(255, 255, 255, 0.04); }
      .side-link.active {
        color: var(--text);
        background: rgba(139, 139, 253, 0.1);
        border-color: rgba(139, 139, 253, 0.25);
      }
      .side-link.active svg { color: var(--accent); }
      .side-label {
        font-size: 0.68rem; letter-spacing: 0.14em; text-transform: uppercase;
        color: var(--faint); padding: 0 0.8rem; margin-top: 1.4rem;
        margin-bottom: 0.5rem; font-weight: 500;
      }
      .dot { width: 8px; height: 8px; border-radius: 9999px; flex-shrink: 0; }
      .dot-success { background: #34d399; box-shadow: 0 0 8px rgba(52, 211, 153, 0.6); }
      .btn-primary {
        position: relative; background: #fff; color: #0a0a10;
        transition: all 0.25s ease;
        box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.9), 0 8px 30px -6px rgba(255, 255, 255, 0.2);
        overflow: hidden;
      }
      .btn-primary:hover {
        box-shadow: 0 0 0 1px rgba(255, 255, 255, 1), 0 12px 40px -6px rgba(139, 139, 253, 0.45);
      }
      .btn-ghost {
        border: 1px solid var(--line-strong); color: var(--muted);
        transition: all 0.25s ease;
      }
      .btn-ghost:hover {
        border-color: rgba(255, 255, 255, 0.35); color: var(--text);
        background: rgba(255, 255, 255, 0.03);
      }
      .btn-danger {
        border: 1px solid rgba(251, 113, 133, 0.3); color: #fda4af;
        transition: all 0.25s ease;
      }
      .btn-danger:hover { background: rgba(251, 113, 133, 0.1); border-color: rgba(251, 113, 133, 0.5); }
      .badge-dot { animation: pulse 2.2s ease-in-out infinite; }
      @keyframes pulse {
        0%, 100% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.5); }
        50% { box-shadow: 0 0 0 5px rgba(52, 211, 153, 0); }
      }
      .status-badge {
        display: inline-flex; align-items: center; gap: 0.35rem;
        font-size: 0.7rem; font-weight: 500; padding: 0.15rem 0.6rem;
        border-radius: 9999px;
      }
      .status-on { background: rgba(52, 211, 153, 0.12); color: #6ee7b7; }
      .status-off { background: rgba(255, 255, 255, 0.06); color: var(--muted); }
      .mono { font-family: ui-monospace, "SF Mono", Menlo, monospace; }
      .key-mask { letter-spacing: 0.05em; }
      .input {
        background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line);
        border-radius: 10px; color: var(--text); font-size: 0.875rem;
        padding: 0.6rem 0.85rem; transition: all 0.2s ease;
        outline: none; width: 100%;
      }
      .input:focus {
        border-color: rgba(139, 139, 253, 0.5);
        box-shadow: 0 0 0 3px rgba(139, 139, 253, 0.12);
      }
      .input::placeholder { color: var(--faint); }
      .sidebar-overlay { background: rgba(0, 0, 0, 0.6); backdrop-filter: blur(4px); }
      .reveal {
        opacity: 0; transform: translateY(20px);
        transition: opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1), transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
      }
      .reveal.visible { opacity: 1; transform: none; }
      .toast {
        position: fixed; bottom: 1.5rem; left: 50%; transform: translateX(-50%) translateY(20px);
        background: #12121c; border: 1px solid var(--line-strong);
        color: var(--text); font-size: 0.82rem; padding: 0.6rem 1rem;
        border-radius: 10px; opacity: 0; pointer-events: none;
        transition: all 0.3s ease; z-index: 100;
      }
      .toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
    </style>
  </head>
  <body class="min-h-screen antialiased overflow-x-hidden">
    <div class="flex min-h-screen" id="layout-root"></div>
    <div class="toast" id="toast"></div>

    <!-- ===== 新建 Key 弹层 ===== -->
    <div id="create-modal" class="fixed inset-0 z-50 hidden items-center justify-center p-4">
      <div class="sidebar-overlay absolute inset-0" onclick="closeCreate()"></div>
      <div class="card relative z-10 w-full max-w-md !bg-[#0b0b12] p-6 shadow-2xl">
        <!-- 步骤 1：输入名称 + 选权限 -->
        <div id="create-step-1">
          <div class="flex items-start justify-between">
            <div>
              <h3 class="text-lg font-medium text-white">新建 API Key</h3>
              <p class="mt-1 text-sm text-zinc-400">给它起个名字，并选择权限范围</p>
            </div>
            <button onclick="closeCreate()" class="rounded-lg p-1.5 text-zinc-500 hover:bg-white/5 hover:text-white">
              <svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
          </div>
          <div class="mt-5">
            <label class="text-xs font-medium text-zinc-400" for="new-key-name">名称</label>
            <input id="new-key-name" class="input mt-2" placeholder="例如：本地开发 / CI 流水线 / 生产 Agent" />
          </div>
          <div class="mt-4">
            <span class="text-xs font-medium text-zinc-400">权限范围（可多选，最小化原则）</span>
            <div class="mt-2 space-y-2">
              <label class="flex cursor-pointer items-start gap-3 rounded-xl border border-white/10 p-3 transition-colors hover:border-white/20 has-[:checked]:border-indigo-400/50 has-[:checked]:bg-indigo-400/5">
                <input type="checkbox" name="key-scope" value="notify:send" class="mt-0.5" checked />
                <span>
                  <span class="block text-sm text-zinc-200">上报 <code class="mono text-[11px] text-zinc-500">notify:send</code></span>
                  <span class="mt-0.5 block text-[11px] text-zinc-500">Agent / CI 用来 POST 通知。前缀 ant_live_</span>
                </span>
              </label>
              <label class="flex cursor-pointer items-start gap-3 rounded-xl border border-white/10 p-3 transition-colors hover:border-white/20 has-[:checked]:border-emerald-400/50 has-[:checked]:bg-emerald-400/5">
                <input type="checkbox" name="key-scope" value="notify:receive" class="mt-0.5" />
                <span>
                  <span class="block text-sm text-zinc-200">接收 <code class="mono text-[11px] text-zinc-500">notify:receive</code></span>
                  <span class="mt-0.5 block text-[11px] text-zinc-500">插件 / 设备用来建立 WebSocket 长连接接收。前缀 ant_recv_</span>
                </span>
              </label>
              <label class="flex cursor-pointer items-start gap-3 rounded-xl border border-white/10 p-3 transition-colors hover:border-white/20 has-[:checked]:border-amber-400/50 has-[:checked]:bg-amber-400/5">
                <input type="checkbox" name="key-scope" value="devices:read" class="mt-0.5" />
                <span>
                  <span class="block text-sm text-zinc-200">设备查询 <code class="mono text-[11px] text-zinc-500">devices:read</code></span>
                  <span class="mt-0.5 block text-[11px] text-zinc-500">只读查看设备列表，用于脚本巡检</span>
                </span>
              </label>
            </div>
            <p class="mt-2.5 text-[11px] leading-relaxed text-zinc-600">
              权限最小化：上报与接收分开，泄露一个 Key 不会波及另一头。
            </p>
            <p id="create-error" class="mt-2 hidden text-xs text-rose-300"></p>
          </div>
          <div class="mt-6 flex justify-end gap-3">
            <button onclick="closeCreate()" class="btn-ghost rounded-xl px-4 py-2 text-sm">取消</button>
            <button onclick="generateKey()" class="btn-primary rounded-xl px-5 py-2 text-sm font-medium">生成 Key</button>
          </div>
        </div>

        <!-- 步骤 2：展示完整 Key（仅一次） -->
        <div id="create-step-2" class="hidden">
          <div class="flex items-start justify-between">
            <div>
              <h3 class="text-lg font-medium text-white">保存你的 Key</h3>
              <p class="mt-1 text-sm text-zinc-400">这是它<b class="text-amber-300">唯一一次完整展示</b></p>
            </div>
            <button onclick="closeCreate()" class="rounded-lg p-1.5 text-zinc-500 hover:bg-white/5 hover:text-white">
              <svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
          </div>
