    <script src="layout.js"></script>
    <script>
      // ==================== 数据层 ====================
      const API = "/v1";
      const SCOPE_META = {
        "notify:send": { label: "上报", color: "background:rgba(96,165,250,0.12);color:#93c5fd" },
        "notify:receive": { label: "接收", color: "background:rgba(52,211,153,0.12);color:#6ee7b7" },
        "devices:read": { label: "设备查询", color: "background:rgba(251,191,36,0.12);color:#fcd34d" },
      };

      // 演示数据（后端不可用时降级展示）
      const DEMO_KEYS = [
        { id: "k_demo1", name: "本地开发", prefix: "ant_live_9f3a", scopes: ["notify:send"], lastUsed: "2 分钟前", enabled: true, created: "2026-06-12" },
        { id: "k_demo2", name: "CI 流水线", prefix: "ant_live_2b1d", scopes: ["notify:send"], lastUsed: "1 小时前", enabled: true, created: "2026-06-28" },
        { id: "k_demo3", name: "桌面插件（接收）", prefix: "ant_recv_9f3a", scopes: ["notify:receive"], lastUsed: "刚刚", enabled: true, created: "2026-07-15" },
        { id: "k_demo4", name: "旧测试 Key", prefix: "ant_live_x8q2", scopes: ["notify:send"], lastUsed: "3 周前", enabled: false, created: "2026-05-30" },
      ];

      let KEYS = [];
      let demoMode = false;
      let newKeyPlain = "";
      let pendingKey = null;

      function toast(msg) {
        const t = document.getElementById("toast");
        t.textContent = msg;
        t.classList.add("show");
        clearTimeout(t._timer);
        t._timer = setTimeout(() => t.classList.remove("show"), 2400);
      }

      function fmtTime(ts) {
        if (!ts) return "从未使用";
        const d = new Date(ts * 1000 || ts);
        if (isNaN(d.getTime())) return String(ts);
        const diff = Date.now() - d.getTime();
        if (diff < 60e3) return "刚刚";
        if (diff < 3600e3) return Math.floor(diff / 60e3) + " 分钟前";
        if (diff < 86400e3) return Math.floor(diff / 3600e3) + " 小时前";
        return d.toISOString().slice(0, 10);
      }

      async function loadKeys() {
        try {
          const res = await fetch(API + "/keys", { credentials: "same-origin" });
          if (!res.ok) throw new Error("HTTP " + res.status);
          const data = await res.json();
          KEYS = (data.keys || data || []).map((k) => ({
            id: k.id,
            name: k.name || "未命名",
            prefix: k.prefix || "ant_????",
            scopes: k.scopes || [],
            lastUsed: fmtTime(k.lastUsedAt || k.last_used_at),
            enabled: k.enabled !== false && k.enabled !== 0,
            created: (k.createdAt || k.created_at) ? new Date((k.createdAt || k.created_at) * (typeof (k.createdAt || k.created_at) === "number" ? 1000 : 1)).toISOString().slice(0, 10) : "",
          }));
          demoMode = false;
        } catch (e) {
          KEYS = DEMO_KEYS.slice();
          demoMode = true;
        }
        renderKeys();
      }

      // ==================== 渲染 ====================
      function renderKeys() {
        const el = AnotifyLayout.el;
        const body = document.getElementById("keys-body");
        const activeCount = KEYS.filter((k) => k.enabled).length;
        document.getElementById("keys-summary").textContent =
          KEYS.length + " 个 Key · " + activeCount + " 启用" + (demoMode ? " · 演示数据" : "");

        if (KEYS.length === 0) {
          body.replaceChildren(
            el("tr", {}, el("td", { class: "px-6 py-10 text-center text-sm text-zinc-500", colspan: "6" },
              "还没有 Key。点右上角「+ 新建 Key」创建一个，让 Agent 开始上报。")),
          );
          return;
        }

        body.replaceChildren(
          ...KEYS.map((k) =>
            el("tr", { class: "transition-colors hover:bg-white/[0.02]" },
              el("td", { class: "px-6 py-4" },
                el("div", { class: "text-sm font-medium text-white", text: k.name }),
                el("div", { class: "text-[11px] text-zinc-500", text: k.created ? "创建于 " + k.created : "" })),
              el("td", { class: "px-6 py-4" },
                el("code", { class: "mono key-mask text-[12px] text-zinc-400", text: k.prefix + "••••••••" })),
              el("td", { class: "px-6 py-4" },
                el("div", { class: "flex flex-wrap gap-1.5" },
                  ...k.scopes.map((s) =>
                    el("span", {
                      class: "rounded-full px-2 py-0.5 text-[10px] font-medium",
                      style: SCOPE_META[s] ? SCOPE_META[s].color : "background:rgba(255,255,255,0.06);color:var(--muted)",
                      text: SCOPE_META[s] ? SCOPE_META[s].label : s,
                    })))),
              el("td", { class: "px-6 py-4 text-xs text-zinc-500", text: k.lastUsed }),
              el("td", { class: "px-6 py-4" },
                el("span", { class: "status-badge " + (k.enabled ? "status-on" : "status-off"), text: k.enabled ? "启用" : "已停用" })),
              el("td", { class: "px-6 py-4 text-right" },
                el("div", { class: "inline-flex items-center gap-2" },
                  el("button", {
                    class: "btn-danger rounded-lg px-3 py-1.5 text-xs",
                    onclick: () => revokeKey(k),
                  }, "停用"))))),
        );
      }

      async function revokeKey(k) {
        if (!confirm("确定停用「" + k.name + "」吗？使用它的 Agent 将无法上报。")) return;
        if (demoMode) {
          k.enabled = false;
          renderKeys();
          toast("已停用（演示模式，仅本地生效）");
          return;
        }
        try {
          const res = await fetch(API + "/keys/" + encodeURIComponent(k.id) + "/revoke", {
            method: "POST", credentials: "same-origin",
          });
          if (!res.ok) throw new Error("HTTP " + res.status);
          k.enabled = false;
          renderKeys();
          toast("已停用「" + k.name + "」");
        } catch (e) {
          toast("停用失败：" + e.message);
        }
      }

      // ==================== 新建 Key ====================
      function openCreate() {
        document.getElementById("create-step-1").classList.remove("hidden");
        document.getElementById("create-step-2").classList.add("hidden");
        document.getElementById("create-error").classList.add("hidden");
        document.getElementById("new-key-name").value = "";
        document.querySelectorAll('input[name="key-scope"]').forEach((c, i) => (c.checked = i === 0));
        document.getElementById("create-modal").classList.replace("hidden", "flex");
        document.body.style.overflow = "hidden";
        setTimeout(() => document.getElementById("new-key-name").focus(), 100);
      }
      function closeCreate() {
        document.getElementById("create-modal").classList.replace("flex", "hidden");
        document.body.style.overflow = "";
      }

      function selectedScopes() {
        return Array.from(document.querySelectorAll('input[name="key-scope"]:checked')).map((c) => c.value);
      }

      function demoKeyFor(scopes) {
        const rand = () => Math.random().toString(36).slice(2, 10);
        const prefix = scopes.includes("notify:receive") && !scopes.includes("notify:send") ? "ant_recv_" : "ant_live_";
        return (prefix + rand() + rand()).slice(0, 28);
      }

      async function generateKey() {
        const name = document.getElementById("new-key-name").value.trim() || "未命名 Key";
        const scopes = selectedScopes();
        const errEl = document.getElementById("create-error");
        if (scopes.length === 0) {
          errEl.textContent = "请至少选择一个权限范围";
          errEl.classList.remove("hidden");
          return;
        }
        errEl.classList.add("hidden");

        if (demoMode) {
          newKeyPlain = demoKeyFor(scopes);
          pendingKey = {
            id: "k_" + Date.now(), name: name, prefix: newKeyPlain.slice(0, 13),
            scopes: scopes, lastUsed: "从未使用", enabled: true,
            created: new Date().toISOString().slice(0, 10),
          };
          showStep2();
          return;
        }

        try {
          const res = await fetch(API + "/keys", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            credentials: "same-origin",
            body: JSON.stringify({ name: name, scopes: scopes }),
          });
          if (!res.ok) {
            const data = await res.json().catch(() => ({}));
            throw new Error(data.error || "HTTP " + res.status);
          }
          const data = await res.json();
          newKeyPlain = data.key || data.plaintext || "";
          if (!newKeyPlain) throw new Error("服务端未返回 Key 明文");
          pendingKey = {
            id: data.id || ("k_" + Date.now()),
            name: data.name || name,
            prefix: data.prefix || newKeyPlain.slice(0, 13),
            scopes: data.scopes || scopes,
            lastUsed: "从未使用", enabled: true,
            created: new Date().toISOString().slice(0, 10),
          };
          showStep2();
        } catch (e) {
          errEl.textContent = "创建失败：" + e.message + "（后端未就绪时可先体验演示模式）";
          errEl.classList.remove("hidden");
        }
      }

      function showStep2() {
        document.getElementById("new-key-value").textContent = newKeyPlain;
        document.getElementById("create-step-1").classList.add("hidden");
        document.getElementById("create-step-2").classList.remove("hidden");
      }

      function copyNewKey(btn) {
        navigator.clipboard.writeText(newKeyPlain).then(() => {
          const orig = btn.textContent;
          btn.textContent = "已复制 ✓";
          setTimeout(() => (btn.textContent = orig), 1500);
        }).catch(() => toast("复制失败，请手动选择复制"));
      }

      function finishCreate() {
        if (pendingKey) {
          KEYS.unshift(pendingKey);
          renderKeys();
        }
        pendingKey = null;
        newKeyPlain = "";
        closeCreate();
        toast("Key 已创建");
      }

      window.addEventListener("keydown", (e) => {
        if (e.key === "Escape") closeCreate();
      });

      // ==================== 页面组装 ====================
      document.getElementById("layout-root").innerHTML = AnotifyLayout.render({
        active: "keys",
        title: "API Keys",
        subtitle: "Agent 用它上报通知",
        actions: '<button onclick="openCreate()" class="btn-primary rounded-xl px-4 py-2 text-sm font-medium">+ 新建 Key</button>',
        content: `
          <div class="reveal visible">
            <h2 class="font-display text-3xl text-white">API Keys</h2>
            <p class="mt-1.5 max-w-2xl text-sm leading-relaxed text-zinc-400">
              Agent 携带 Key 调用 <code class="mono rounded bg-white/5 px-1.5 py-0.5 text-[12px] text-zinc-300">POST /v1/notify</code> 上报通知。
              Key 仅在创建时完整展示一次，服务端只存哈希——请立即妥善保存。
            </p>
          </div>

          <section class="card reveal visible p-5">
            <div class="flex items-center justify-between">
              <div class="text-xs font-medium text-zinc-500">上报接口</div>
              <a href="docs.html#notify" class="flex items-center gap-1 text-xs text-zinc-400 transition-colors hover:text-white">
                查看完整接口文档
                <svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
              </a>
            </div>
            <div class="mt-3 flex flex-wrap items-center gap-2">
              <code class="mono rounded-lg bg-black/50 px-3.5 py-2 text-[12.5px] text-zinc-200 ring-1 ring-white/10">POST /v1/notify</code>
              <span class="text-xs text-zinc-500">Header:</span>
              <code class="mono rounded-lg bg-white/[0.04] px-3 py-2 text-[12px] text-zinc-300 ring-1 ring-white/10">Authorization: Bearer ant_live_…</code>
            </div>
          </section>

          <section class="card reveal visible overflow-hidden">
            <div class="flex items-center justify-between border-b border-white/[0.06] px-6 py-4">
              <div class="text-sm font-medium text-white">我的 Keys</div>
              <span class="text-xs text-zinc-500" id="keys-summary"></span>
            </div>
            <div class="overflow-x-auto">
              <table class="w-full text-sm">
                <thead>
                  <tr class="border-b border-white/[0.05] text-left text-xs text-zinc-500">
                    <th class="px-6 py-3.5 font-medium">名称</th>
                    <th class="px-6 py-3.5 font-medium">Key 前缀</th>
                    <th class="px-6 py-3.5 font-medium">权限</th>
                    <th class="px-6 py-3.5 font-medium">最近使用</th>
                    <th class="px-6 py-3.5 font-medium">状态</th>
                    <th class="px-6 py-3.5 font-medium text-right">操作</th>
                  </tr>
                </thead>
                <tbody id="keys-body" class="divide-y divide-white/[0.04]"></tbody>
              </table>
            </div>
          </section>

          <section class="card reveal visible p-6">
            <div class="flex items-start gap-4">
              <div class="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-amber-400/10">
                <svg class="h-5 w-5 text-amber-300" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                  <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
                  <line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
                </svg>
              </div>
              <div class="text-sm leading-relaxed text-zinc-400">
                <p class="font-medium text-white">Key 的安全实践</p>
                <ul class="mt-1.5 space-y-1 text-zinc-400">
                  <li>· Key 明文<b class="text-zinc-200">只在创建时展示一次</b>，之后无法再次查看，只能重新生成</li>
                  <li>· 服务端仅存 <b class="text-zinc-200">argon2id 哈希</b>，即使数据库泄露也无法还原 Key</li>
                  <li>· 建议<b class="text-zinc-200">每个 Agent / 环境一个 Key</b>，泄露时只停用受影响的那一个</li>
                  <li>· 不要把 Key 提交进代码仓库；用环境变量或密钥管理器注入</li>
                </ul>
              </div>
            </div>
          </section>`,
      });
      AnotifyLayout.mount();
      loadKeys();
    </script>
  </body>
</html>
",
