                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-get">GET</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/notifications</td><td class="px-5 py-2.5 text-zinc-500">通知历史列表</td></tr>
                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-get">GET</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/devices</td><td class="px-5 py-2.5 text-zinc-500">设备列表</td></tr>
                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-post">POST</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/devices</td><td class="px-5 py-2.5 text-zinc-500">订阅（注册）设备</td></tr>
                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-patch">PATCH</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/devices/:id</td><td class="px-5 py-2.5 text-zinc-500">更新设备（开关/过滤/标签）</td></tr>
