                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-ws">WS</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/stream</td><td class="px-5 py-2.5 text-zinc-500">WebSocket 长连接接收</td></tr>
                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-get">GET</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/keys</td><td class="px-5 py-2.5 text-zinc-500">API Key 列表</td></tr>
                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-post">POST</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/keys</td><td class="px-5 py-2.5 text-zinc-500">新建 API Key</td></tr>
                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-post">POST</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/auth/register · login</td><td class="px-5 py-2.5 text-zinc-500">Passkey 注册 / 登录</td></tr>
                    <tr class="hover:bg-white/[0.02]"><td class="px-5 py-2.5"><span class="method m-get">GET</span></td><td class="px-2 py-2.5 mono text-zinc-300">/v1/vapid-public-key</td><td class="px-5 py-2.5 text-zinc-500">VAPID 公钥（订阅用）</td></tr>
