          <!-- ===== POST /v1/notify ===== -->
          <section id="notify" class="doc-anchor mt-16 reveal visible">
            <div class="flex items-center gap-3">
              <span class="method m-post">POST</span>
              <code class="mono text-lg text-white">/v1/notify</code>
