    "title": "部署完成",
    "status": "success",
    "body": "构建成功，已发布到生产环境",
    "link": "pi://session/sess_8f3a2c",
    "agentId": "deploy-bot",
    "sessionId": "sess_8f3a2c",
    "cwd": "/repo/prod-backend",
    "durationMs": 24000,
    "model": "anthropic/claude-4",
    "deviceTags": ["工作"]
  }'</span></div>
            </div>

            <div class="mt-5 grid gap-4 lg:grid-cols-2">
