    console.log('failed reqs: ' + JSON.stringify(failedReqs.slice(0,5)));
    console.log('overflow: ' + JSON.stringify(overflow));
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
