const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ channel: 'chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto('http://localhost:8921/web/docs.html', { waitUntil: 'load', timeout: 20000 });
  await page.waitForTimeout(1200);
  const info = await page.evaluate(() => {
    const oxa = document.querySelector('.overflow-x-auto');
    const table = oxa.querySelector('table');
    const cs = getComputedStyle(oxa);
    const walk = [];
    let el = oxa;
    while (el && el !== document.body) {
      walk.push(el.tagName + '.' + String(el.className).slice(0, 30) + ' w=' + Math.round(el.getBoundingClientRect().width));
      el = el.parentElement;
    }
    return {
      oxaWidth: Math.round(oxa.getBoundingClientRect().width),
      oxaClientWidth: oxa.clientWidth,
      oxaScrollWidth: oxa.scrollWidth,
      oxaMaxWidth: cs.maxWidth,
      contain: cs.contain,
      overflowX: cs.overflowX,
      tableWidth: Math.round(table.getBoundingClientRect().width),
      tableOffsetWidth: table.offsetWidth,
      mediaMatches: matchMedia('(max-width: 640px)').matches,
      chain: walk,
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
"; pkill -f "http.server 8921" 2>/dev/null; echo done

