/* 网格/卡片子元素最小宽度归零，防长内容撑破容器（flex/grid min-width:auto 陷阱） */
.grid > *, .card, .code-block { min-width: 0; }
/* 移动端：卡片内横滚容器收缩到视口内，内容在其内部滚动 */
@media (max-width: 640px) {
  .overflow-x-auto {
    max-width: calc(100vw - 5rem);
    contain: inline-size;
  }
}
.doc-anchor { scroll-margin-top: 5rem; }

