arguments.command:
cd /Users/zheng/code/anotify/.pi-orchestrator/worktrees/wt-feadmin && (python3 -m http.server 8924 >/dev/null 2>&1 &) && sleep 1 && node -e "
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ channel: 'chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto('http://localhost:8924/web/docs.html', { waitUntil: 'load', timeout: 20000 });
  await page.waitForTimeout(1500);
  const docOverflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  const culprits = await page.evaluate(() => {
    const vw = window.innerWidth; const out = [];
    for (const el of document.querySelectorAll('body *')) {
      const r = el.getBoundingClientRect();
      if (r.right > vw + 2 && el.parentElement && el.parentElement.getBoundingClientRect().right <= vw + 2) {
        out.push(el.tagName + '.' + String(el.className).slice(0,40) + ' r=' + Math.round(r.right));
      }
    }
    return out.slice(0, 8);
  });
  console.log('docs mobile | docOverflow=' + docOverflow + 'px | 源头溢出=' + JSON.stringify(culprits));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
"; pkill -f "http.server 8924" 2>/dev/null; echo done

