arguments.command:
cd /Users/zheng/code/anotify/.pi-orchestrator/worktrees/wt-feadmin && (python3 -m http.server 8925 >/dev/null 2>&1 &) && sleep 1 && node -e "
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ channel: 'chrome', headless: true, args: ['--no-sandbox'] });
  console.log('========== 最终验收 ==========');
  for (const pn of ['keys', 'security', 'docs']) {
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
    const perr = [];
    page.on('pageerror', e => perr.push(String(e).slice(0, 80)));
    await page.goto('http://localhost:8925/web/' + pn + '.html', { waitUntil: 'load', timeout: 20000 });
    await page.waitForTimeout(1300);
    const title = await page.title();
    // 桌面滚动到底
    await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
    await page.waitForTimeout(400);
    const d = await page.evaluate(() => ({ y: window.scrollY, h: document.documentElement.scrollHeight - window.innerHeight }));
    // 桌面文档溢出
    const docOvf = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    // 移动端溢出
    await page.setViewportSize({ width: 390, height: 844 });
    await page.waitForTimeout(500);
    const mOvf = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    // 截图
    await page.setViewportSize({ width: 1280, height: 800 });
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(400);
    await page.screenshot({ path: '../../.pi/web-verify-shots/t14-' + pn + '-final.png', fullPage: true });
    const scrollOK = d.h <= 0 ? 'N/A(单屏)' : (Math.abs(d.y - d.h) < 5 ? 'OK' : 'FAIL(' + Math.round(d.y) + '/' + Math.round(d.h) + ')');
    console.log(pn.padEnd(9) + ' | ' + title + ' | JS错误:' + perr.length + ' | 滚动到底:' + scrollOK + ' | 桌面溢出:' + docOvf + 'px | 移动溢出:' + mOvf + 'px');
    if (perr.length) console.log('  JS错误: ' + JSON.stringify(perr));
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
"; pkill -f "http.server 8925" 2>/dev/null; echo cleanup-done

